if ( error )
return error;

#ifdef TT_CONFIG_OPTION_GX_VAR_SUPPORT
{
FT_ULong  fvar_len;

FT_ULong  version;
FT_ULong  offset;

FT_UShort  num_axes;
FT_UShort  axis_size;
FT_UShort  num_instances;
FT_UShort  instance_size;

