void TabStripGtk::DestroyDraggedTab(TabGtk* tab) {
  StopAnimation();

  std::vector<TabData>::iterator it = tab_data_.begin();
  for (; it != tab_data_.end(); ++it) {
    if (it->tab == tab) {
      if (!model_->closing_all())
