        return;

    int idx = hwc->idx - INTEL_PMC_IDX_FIXED;
    u64 ctrl_val, mask;

    mask = 0xfULL << (idx * 4);

    rdmsrl(hwc->config_base, ctrl_val);
    ctrl_val &= ~mask;
    wrmsrl(hwc->config_base, ctrl_val);
}

